#!/bin/bash
set -euo pipefail
umask 077
python3 -B - <<'P'
import base64,hashlib,json,os,stat,subprocess
from pathlib import Path
B=Path('/project/community/jjyeung/okh7/i_1be16f28')
records={'4.json': {'old': '73d274495f8d6bf9ae2bc3e3895bce5f5ca5ad29b8f729692389fb8209892009', 'new': '315ff17de27516e479cf0222913db24a474fcca4daedb421931d51ad1eebe5dd', 'data': ''}, 'a_8c74b291.sh': {'old': None, 'new': '22ddf08a37c911682043c0149f4ae5923e98c11afb0235245b23a875227e86b3', 'data': ''}, 'd.py': {'old': 'a82b01974363e15574a65820876e29a3c8a0b4b076f144bc9642c3667848f548', 'new': '4f83f57f87fcec81a67d0ea1f63919e260ee6fc2f5db817f126b258b839c849a', 'data': ''}, 'd_e48ab85bb9364aab.json': {'old': None, 'new': 'e48ab85bb9364aab228da7b23033605935e384761f76b0e6527c5e221b1c14b4', 'data': ''}, 'd_eac5f9f01587803b.json': {'old': None, 'new': 'eac5f9f01587803b2402f80cc310b75ec1f960270a6bc059416b1e1407b1e7c9', 'data': ''}, 'go.template.json': {'old': '62409c4655ac4e632e70be08c46a13be8c4397c5b9d8b7f775a9132fa9347931', 'new': '57aaf502a2e30cff4cb8828ee5cb4c7370b354ad9a5e7084139f8d632d579082', 'data': ''}, 'ids.json': {'old': 'a8fdb52352345d914fdf208f1ed1532f9a2e88f2215113d792623d8897e130cf', 'new': 'f7583d7737fd2c23fc88872aa8b9f5c59de0d25cf9378b3ede26b627624a7a6d', 'data': ''}, 'jb.sh': {'old': '45fc96cfdc12b3ae7882c8e698ec471d419efe7eb9ceab2b6d54c3af3bd30183', 'new': '3f4b074e93eb76dcfacb4504f85bd07a1f46dce51156df5efa99daae733f57db', 'data': ''}, 'o.sh': {'old': 'a7e4996174cdd819e8a06f6239723e702e6939a7339f477fec8a1a1bff47ba21', 'new': '02703767d07c88d7837b3e277d2f0f7c6206a201623ac881b91630a687584946', 'data': ''}, 'over.json': {'old': '8620b4bdadb2103ec7caf249282b12a61437109ba363dae39b1218076d45c85f', 'new': 'f5668d9628928eaf690c900260461cec6a7617c100d9a80160d9b356b08c6e4a', 'data': ''}, 'review.json': {'old': 'c2ca11571d9a0b64e9ed7b7c432a2252649153f9cbe19524563bab2ed5b729ab', 'new': '39819bad1f534909c6ca6083e18fbc7c300acb46ae2a6d5ededb9bfda43d26ea', 'data': ''}, 's.sh': {'old': 'c9d25742f65aeffc7e2e0f1b855ab2a592d37500db921f623bdee0710c87b5fc', 'new': 'b542f7fc5a108ce146b5668272efd8ad2de40cb7b59d1b049398f67b899dbc6d', 'data': ''}, 'staging.json': {'old': '79458e943c1dfae784b3702d6361bbf1532089b6aeb27adf9f5e9326ce01dd1e', 'new': 'dd0ebb4728b2ffdfd9a67306e80b0bb263df982e5c652fb906ed4c236db29fc2', 'data': ''}, 'sums.txt': {'old': 'd23b6e394df2a6de73c4eec95e83e7dda6cf84348494b962e2c796dfcaea8958', 'new': '25a9554487488c2d303e766c67f6bc3ce34f6519954ffa682cb9830ca02c9f28', 'data': ''}, 'z.sh': {'old': 'b5f6e498863b872fd5f654f8b566f0c7bf28dd0730b174f7a7bd3c97c207b967', 'new': 'cd5ed86d7f0ef19e30dfbb0b631bcb805868bc76e3b7494e1fccaf43ae44018e', 'data': ''}}
old_identity='6e4f2846e45377f5b25da0113bf70d625d41d0bee80ae26840d2dee839f85965'
new_kit='3fdda0fb'
new_root='39504485'

backup=B/'v_8'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def exists(p):return p.exists() or p.is_symlink()
# All refusals precede changes; mutable evidence is checked semantically and retained verbatim.
for p in (B.parent,B):
    if p.is_symlink() or not p.is_dir() or stat.S_IMODE(p.stat().st_mode)!=0o700:
        raise SystemExit('Patch refused: directory must be private')
for p in (backup,B.parent/('x_'+new_kit),B.parent/'r'/new_root):
    if exists(p):raise SystemExit('Patch refused: target exists')
prepared={}
for n,r in records.items():
    p=B/n
    if r['old'] is None:
        if exists(p):raise SystemExit('Patch refused: new target exists '+n)
    elif not stat.S_ISREG(p.lstat().st_mode) or p.stat().st_nlink!=1:
        raise SystemExit('Patch refused: linked target '+n)
    if n in ('review.json','staging.json'):
        value=json.loads(p.read_text())
        if value.get('config_sha256')!=old_identity:raise SystemExit('Patch refused: foreign evidence '+n)
    elif r['old'] is not None and sha(p)!=r['old']:raise SystemExit('Patch refused: old bytes differ '+n)
    raw=base64.b64decode(r['data'],validate=True)
    if hashlib.sha256(raw).hexdigest()!=r['new']:raise SystemExit('Patch refused: embedded digest '+n)
    prepared[n]=(raw,stat.S_IMODE(p.stat().st_mode) if r['old'] is not None else 0o600)
subprocess.run(['sha256sum','-c','sums.txt'],cwd=B,check=True)
# Retire identity-bound evidence and derived directories; leave routing archive/t/u and old KH alone.
retire=['p','e','q','p.json','e.json','c.json','archive.json','gate.json','ready.json',
        'result.json','compare.json','anon.json','go.json']
for n in retire:
    if (B/n).is_symlink():raise SystemExit('Patch refused: linked evidence '+n)
backup.mkdir(mode=0o700)
prior={n:sha(B/n) for n,r in records.items() if r['old'] is not None}
for n,(raw,mode) in prepared.items():
    with (backup/(n+'.new')).open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    (backup/(n+'.new')).chmod(mode)
for n in retire:
    if exists(B/n):(B/n).rename(backup/n)
for n in records:
    if n in prior:(B/n).rename(backup/n)
    (backup/(n+'.new')).rename(B/n)
    if sha(B/n)!=records[n]['new'] or (n in prior and sha(backup/n)!=prior[n]):raise SystemExit('Patch readback differs')
subprocess.run(['sha256sum','-c','sums.txt'],cwd=B,check=True)
print('Patch verified. Selection pins verified. Independent review, certification and the production CPU proof are required before go.json.')
P
